bool TextsAreUnique(
  const std::vector<std::wstring>& texts
) {
  std::unordered_set<std::wstring> seen = std::unordered_set<std::wstring>();
  for (const std::wstring& text : texts) {
    if (seen.find(text) != seen.end()) {
      return false;
    }
    seen.insert(text);
  }
  return true;
}

bool NumbersAreUniqueBetweenZeros(
  const std::vector<int64_t>& numbers
) {
  std::unordered_set<int64_t> seen = std::unordered_set<int64_t>();
  for (int64_t number : numbers) {
    if (number == 0) {
      seen = std::unordered_set<int64_t>();
      continue;
    }
    if (seen.find(number) != seen.end()) {
      return false;
    }
    seen.insert(number);
  }
  return true;
}

