/**
 * Give out the checks of the values of the \p shape.
 */
const std::vector<Check>& ChecksOf(Shape shape) {
  static const std::vector<Check> kNoChecks;

  switch (shape) {
    case Shape::kCode: {
      static const std::vector<Check> checks = {
        {
          &Code_0,
          L"Code must not be empty."
        }
      };
      return checks;
    }
    case Shape::kSomething: {
      static const std::vector<Check> checks = {
        {
          &Something_0,
          L"Optional texts must be unique, apart from the reserved ones."
        },
        {
          &Something_1,
          L"Optional texts must not share any text with texts."
        },
        {
          &Something_2,
          L"Kind must not be special."
        },
        {
          &Something_3,
          L"Number of numbers must not be lucky."
        },
        {
          &Something_4,
          L"Number must not be lucky."
        },
        {
          &Something_5,
          L"Text must not be reserved."
        },
        {
          &Something_6,
          L"Texts must be of unique lengths."
        },
        {
          &Something_7,
          L"Flags must be either all true or all false."
        },
        {
          &Something_8,
          L"Codes must be unique."
        },
        {
          &Something_9,
          L"Kinds must be unique."
        },
        {
          &Something_10,
          L"Numbers must be unique between the zeros."
        },
        {
          &Something_11,
          L"Optional kind must not be special."
        },
        {
          &Something_12,
          L"Kinds and the optional kind, if any, must contain a kind "
          L"which is not special."
        },
        {
          &Something_13,
          L"At most one text must be reserved."
        },
        {
          &Something_14,
          L"Numbers must be smaller than 1000."
        },
        {
          &Something_15,
          L"Texts must be at most 10 characters long."
        },
        {
          &Something_16,
          L"Texts must be unique."
        }
      };
      return checks;
    }
    case Shape::kCollection: {
      static const std::vector<Check> checks = {
        {
          &Collection_0,
          L"Texts must contain a text which is not reserved, if any."
        },
        {
          &Collection_1,
          L"Optional texts must not share any text with texts."
        },
        {
          &Collection_2,
          L"Directions must contain south if they contain north."
        },
        {
          &Collection_3,
          L"Numbers must be greater than -1000."
        },
        {
          &Collection_4,
          L"There must be at most five numbers."
        },
        {
          &Collection_5,
          L"Texts must not contain the forbidden text."
        }
      };
      return checks;
    }
    case Shape::kINT64:
      // NOTE (mristin):
      // These values are verified by the nested verification.
      return kNoChecks;
    default:
      throw std::logic_error(
        common::Concat(
          "Unexpected shape: ",
          std::to_string(static_cast<std::uint32_t>(shape))
        )
      );
  }
}

